(function(root){
  const columns=['external_id','name','target','object','goal','preconditions','inputMode','input','datasetRef','sampleId','steps','expected','criteria','evidence','forbidden','referenceRef','source'];
  const headers={external_id:'外部用例ID',name:'用例名称',target:'对象类型',object:'被测对象',goal:'验证目标',preconditions:'前置条件',inputMode:'输入方式',input:'实际输入',datasetRef:'数据集版本',sampleId:'样本ID',steps:'执行步骤',expected:'预期结果',criteria:'判定条件',evidence:'证据要求',forbidden:'禁止行为',referenceRef:'参考资产版本',source:'来源与用途'};
  function delimited(raw,delimiter){const rows=[];let row=[],cell='',quoted=false,closed=false;for(let i=0;i<raw.length;i++){const c=raw[i];if(quoted){if(c==='"'&&raw[i+1]==='"'){cell+='"';i++;}else if(c==='"'){quoted=false;closed=true;}else cell+=c;}else if(c==='"'){if(cell||closed)throw Error('引号位置不正确，请将含逗号或换行的单元格整体加引号。');quoted=true;}else if(c===delimiter){row.push(cell);cell='';closed=false;}else if(c==='\n'||c==='\r'){if(c==='\r'&&raw[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';closed=false;}else {if(closed&&!/\s/.test(c))throw Error('闭合引号后出现多余字符。');cell+=c;}}if(quoted)throw Error('存在未闭合引号，未创建任何草稿。');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
  function parse(raw){raw=String(raw||'').replace(/^\uFEFF/,'').replace(/^(?:\r?\n)+/,'');if(!raw.trim())throw Error('先粘贴表格内容，或选择CSV / JSON文件。');if(raw.trimStart()[0]==='['||raw.trimStart()[0]==='{'){const v=JSON.parse(raw);const rows=Array.isArray(v)?v:v.cases;if(!Array.isArray(rows)||rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('JSON需为用例对象数组，或含cases数组的对象。');return rows;}const firstLine=raw.split(/\r?\n/)[0];const rows=delimited(raw,firstLine.includes('\t')?'\t':',');const keys=rows.shift().map(s=>s.trim());if(new Set(keys).size!==keys.length||keys.some(k=>!k))throw Error('表头不能为空或重复。');return rows.map((r,i)=>{if(r.length!==keys.length)throw Error('第'+(i+2)+'行列数与表头不一致。');return Object.fromEntries(keys.map((k,j)=>[k,r[j]]));});}
  const text=v=>v==null?'':typeof v==='string'?v:JSON.stringify(v);
  function plan(records,mapping,namespace,existing){if(!namespace.trim())throw Error('请填写导入来源名称，用于识别重复导入。');if(!records.length||records.length>500)throw Error('每批需要1—500行用例；500行为本原型交互上限。');const seen=new Set();return records.map((r,i)=>{const spec={...CaseAuthoring.blank()};for(const key of columns.filter(k=>k!=='external_id'))spec[key]=text(r[mapping[key]]);if(!spec.target)spec.target='Agent';if(!spec.inputMode)spec.inputMode='inline';spec.inputMode=({'直接填写':'inline','引用数据集':'dataset'})[spec.inputMode]||spec.inputMode;const id=text(r[mapping.external_id]).trim();const reasons=[];if(!id)reasons.push('缺外部用例ID');if(!spec.name.trim())reasons.push('缺用例名称');if(!['模型','Agent','非Agent应用'].includes(spec.target))reasons.push('对象类型需为模型、Agent或非Agent应用');if(!['inline','dataset'].includes(spec.inputMode))reasons.push('输入方式请填写“直接填写”（inline）或“引用数据集”（dataset）');if(id&&seen.has(id))reasons.push('本批重复ID');if(id)seen.add(id);if(existing.some(a=>a.importNamespace===namespace&&a.importId===id))reasons.push('同来源ID已导入，不覆盖原版本');return {line:i+1,id,spec,record:r,issues:reasons,gaps:CaseAuthoring.missing(spec)};});}
  function defaultMap(keys){return Object.fromEntries(columns.map(k=>[k,keys.includes(k)?k:keys.includes(headers[k])?headers[k]:'']));}
  const api={columns,headers,parse,plan,defaultMap};root.CaseBulk=api;if(typeof module==='object'&&module.exports)module.exports=api;
})(typeof window==='undefined'?globalThis:window);
if(typeof document!=='undefined'){
  let bulk={raw:'',namespace:'',records:null,mapping:{},preview:null,confirmedRaw:''};
  function caseBulkOpen(){bulk={raw:'',namespace:'',records:null,mapping:{},preview:null,confirmedRaw:''};bulkRender();}
  function bulkRender(){modal('批量编写／导入用例',`<div class="cb-builder stack"><p>可从Excel复制整块单元格粘贴，也可导入UTF-8 CSV／JSON。每行是一条用例，导入后分别保存为草稿。</p><div class="flex wrap"><button class="btn" data-action="bulk-example">载入三条业务示例</button><button class="btn" data-action="bulk-template">下载CSV模板</button><label class="btn">选择CSV／TSV／JSON文件<input type="file" id="case-bulk-file" accept=".csv,.tsv,.json" hidden></label></div><label class="cb-field"><span>导入来源名称 *</span><input class="input" id="case-bulk-namespace" value="${esc(bulk.namespace)}" placeholder="例如：订单回归用例-2026Q4"><small>相同导入来源名称＋相同外部用例ID再次导入会隔离，保留原版本。合并、更新策略待评审。</small></label><label class="cb-field"><span>表格或JSON内容</span><textarea class="input" id="case-bulk-raw" rows="8" placeholder="粘贴表头和多行用例数据">${esc(bulk.raw)}</textarea><small>支持单元格内换行和引号。Excel .xlsx请先复制单元格或另存为CSV；当前未实现原生.xlsx解析。</small></label><div id="case-bulk-error" role="alert"></div>${bulk.records?`<details open><summary>核对列与字段的对应关系 · ${bulk.records.length} 行</summary><div class="grid3 mt">${CaseBulk.columns.map(k=>`<label class="cb-field"><span>${CaseBulk.headers[k]}${['external_id','name'].includes(k)?' *':''}</span><select class="input" data-bulk-map="${k}"><option value="">暂不映射</option>${Object.keys(bulk.records[0]||{}).map(c=>`<option value="${esc(c)}" ${bulk.mapping[k]===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`).join('')}</div></details>`:''}<div id="case-bulk-preview">${bulk.preview?`<div class="notice ${bulk.preview.some(r=>r.issues.length)?'warn':'success'}">可创建 ${bulk.preview.filter(r=>!r.issues.length).length} 条草稿；隔离 ${bulk.preview.filter(r=>r.issues.length).length} 行。待补齐项不会被填成通过。</div>${table(['记录序号','外部ID／名称','处理结果','待补齐'],bulk.preview.map(r=>[r.line,esc(r.id+' / '+r.spec.name),r.issues.length?esc(r.issues.join('；')):'新建独立草稿',esc(r.gaps.map(g=>g.label).join('、')||'描述齐全，仍待校验审核')]))}`:''}</div><div class="cb-static">此表头是用例录入的交互草案，可通过列映射适配现有表格。文件附件、嵌套多轮脚本、参数化模板、外部测试系统同步的约定和规模仍需单独评审。</div></div>`,btn('取消','close')+btn('读取并对应字段','bulk-read')+btn('预览与检查','bulk-preview')+btn('仅导入合格行草稿','bulk-import','','primary'),true);document.querySelector('.modal').classList.add('cb-modal');document.querySelector('[data-action="bulk-import"]').disabled=!bulk.preview?.some(r=>!r.issues.length);}
  function bulkRead(){bulk.raw=document.getElementById('case-bulk-raw').value;bulk.namespace=document.getElementById('case-bulk-namespace').value.trim();}
  function bulkError(e){document.getElementById('case-bulk-error').innerHTML=notice(esc(e.message),'error');document.getElementById('case-bulk-error').scrollIntoView({block:'nearest'});}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action^="bulk-"]');if(!b)return;try{bulkRead();switch(b.dataset.action){case 'bulk-example':{bulk.namespace=bulk.namespace||'人工业务样例-v1';bulk.raw=JSON.stringify(['office','pet','rag'].map((k,i)=>({external_id:'EXAMPLE-0'+(i+1),...CaseAuthoring.examples[k]})),null,2);bulk.records=null;bulk.preview=null;bulkRender();break;}case 'bulk-template':{const row={external_id:'CASE-001',...CaseAuthoring.examples.office};const csv=CaseBulk.columns.map(k=>CaseBulk.headers[k]).join(',')+'\r\n'+CaseBulk.columns.map(k=>'"'+String(row[k]||'').replace(/"/g,'""')+'"').join(',');download('用例批量录入模板.csv','\uFEFF'+csv);break;}case 'bulk-read':{bulk.records=CaseBulk.parse(bulk.raw);if(!bulk.records.length||bulk.records.length>500)throw Error('本批应包含1—500行。');bulk.mapping=CaseBulk.defaultMap(Object.keys(bulk.records[0]));bulk.preview=null;bulkRender();break;}case 'bulk-preview':{if(!bulk.records)throw Error('先读取表格并核对映射。');const now=CaseBulk.parse(bulk.raw);bulk.preview=CaseBulk.plan(now,bulk.mapping,bulk.namespace,S.customAssets||[]);bulk.confirmedRaw=bulk.raw;bulk.confirmedNamespace=bulk.namespace;bulk.confirmedMapping=JSON.stringify(bulk.mapping);bulkRender();break;}case 'bulk-import':{if(!guard('engineer'))return;if(!bulk.preview||bulk.confirmedRaw!==bulk.raw||bulk.confirmedNamespace!==bulk.namespace||bulk.confirmedMapping!==JSON.stringify(bulk.mapping))throw Error('输入、来源或映射已变更，请重新预览后再导入。');const rows=CaseBulk.plan(CaseBulk.parse(bulk.raw),bulk.mapping,bulk.namespace,S.customAssets||[]).filter(r=>!r.issues.length);if(!rows.length)throw Error('没有可导入的行，请先处理隔离原因。');const batch='BATCH-'+Date.now().toString(36);S.customAssets=S.customAssets||[];for(const [i,r] of rows.entries())S.customAssets.push({id:'AS-DRAFT-CASE-'+batch+'-'+i,kind:'case',type:'评测用例',group:1,name:r.spec.name,targets:[r.spec.target],object:r.spec.object,source:r.spec.source,caseSpec:r.spec,content:CaseAuthoring.content(r.spec),version:'r1',status:'草稿',owner:roleNames[S.role],validated:false,expertConfirmed:false,demandAsset:true,importNamespace:bulk.namespace,importId:r.id,importBatch:batch,importLine:r.line,importOriginal:r.record,count:'批量录入 · '+(r.gaps.length?'待补齐':'待校验')});log('批量创建用例草稿',batch+' / '+rows.length+'条');S.assetGroup=1;S.assetType='case';S.assetSearch='';S.assetObject='all';close();go('assets');toast('已保存'+rows.length+'条独立草稿；隔离行未导入，未发布任何用例。','success');break;}}}catch(err){bulkError(err);}});
  function bulkInvalidate(){bulk.preview=null;const p=document.getElementById('case-bulk-preview');if(p)p.innerHTML='';const b=document.querySelector('[data-action="bulk-import"]');if(b)b.disabled=true;const e=document.getElementById('case-bulk-error');if(e)e.innerHTML=notice('内容、来源或映射已修改，请重新预览后再导入。','warn');}
  document.addEventListener('input',e=>{if(['case-bulk-raw','case-bulk-namespace'].includes(e.target.id))bulkInvalidate();});
  document.addEventListener('change',async e=>{if(e.target.dataset.bulkMap){bulk.mapping[e.target.dataset.bulkMap]=e.target.value;bulkInvalidate();}if(e.target.id==='case-bulk-file'&&e.target.files[0]){const f=e.target.files[0];try{if(f.size>2*1024*1024)throw Error('本原型文件上限2MB，请拆分后导入。');bulkRead();bulk.raw=await f.text();bulk.records=null;bulk.preview=null;bulkRender();}catch(err){bulkError(err);}}});
}
